  ui_story_5067_50670301_25_dialog_content = "El Delfín Blanco dijo que algunos de los habitantes del pueblo también son muy sabios...",
  ui_story_5067_50670301_26_dialog_content = "Tal vez uno de ellos pueda ayudarme a resolver este problema... ¿Conoces a alguien así?",
  ui_story_5067_50670301_27_dialog_content = "Alguien con conocimientos... Creo que conozco a alguien que encaja en ese perfil...",
