  ui_story_5067_50670301_30_dialog_content = "Con su sabiduría, es posible que pueda guiarte en la dirección correcta.",
  ui_story_5067_50670301_31_dialog_content = "Gracias... Muchas gracias, Dayna. Pensaré en una forma de encontrar a este sabio...",
