  ui_story_5067_50670501_1_dialog_content = "¿Es... Es este el lugar...?",
  ui_story_5067_50670501_2_dialog_content = "Um... Disculpe, pero ¿está disponible la Lady en la Tetera en este momento...?",
  ui_story_5067_50670501_3_dialog_content = "Vaya vaya, si no es Connolly... La nueva reina del pueblo.",
  ui_story_5067_50670501_4_dialog_content = "Déjame adivinar, ¿has tenido algún tipo de problema y necesitas mi consejo?",
