  ui_story_5067_50670501_6_dialog_content = "Nada de lo que sucede en el fondo del mar escapa a mi conocimiento. Vamos a ver...",
  ui_story_5067_50670501_7_dialog_content = "¡Si tu solicitud es digna de consideración!",
  ui_story_5067_50670501_8_dialog_content = "Bueno... Últimamente, la gente del pueblo ha estado viendo y escuchando cosas extrañas...",
  ui_story_5067_50670501_9_dialog_content = "¡Quería saber si podrías decirme la causa de estas alucinaciones!",
  ui_story_5067_50670501_10_dialog_content = "Como reina, tengo que encontrar una manera de deshacerme de ellos...",
