  ui_story_5067_50670501_13_dialog_content = "Seguramente conoces la historia del Señor del Agua, ¿verdad?",
  ui_story_5067_50670501_14_dialog_content = "Eh... B-Bueno, el Señor Aqua estuvo inactivo durante mucho tiempo y realmente no me mencionó nada sobre su pasado.",
  ui_story_5067_50670501_15_dialog_content = "Jeje, así que no tienes idea. ¿Sabías que el Aqua Lord alguna vez fue conocido como el dios del miedo y el dolor?",
