  ui_story_5067_50670501_17_dialog_content = "En efecto. El terrible aspecto del Señor del Agua obligaba a los demás a obedecer por miedo, y su poder absoluto causaba un dolor insoportable a todos los que invadían su territorio.",
  ui_story_5067_50670501_18_dialog_content = "El Señor Acuático fue una deidad verdaderamente peligrosa en su tiempo.",
