  ui_story_5067_50670501_27_dialog_content = "Por supuesto. Es mi deber resolverlo como reina.",
  ui_story_5067_50670501_28_dialog_content = "Simplemente no sé cómo estos fragmentos de poder afectarán a los Anton...",
  ui_story_5067_50670501_29_dialog_content = "Oh... ¿Te preocupan esas cositas?",
  ui_story_5067_50670501_30_dialog_content = "Es perfectamente natural querer los fragmentos del poder del Señor del Agua para ti mismo...",
  ui_story_5067_50670501_31_dialog_content = "Reconstruir un templo de fe debería ser bastante sencillo con ese tipo de poder.",
  ui_story_5067_50670501_32_dialog_content = "Sería bueno darles un nuevo hogar lo más pronto posible... pero...",
  ui_story_5067_50670501_33_dialog_content = "Te preocupa que reconstruir su templo restaure su poder original... ¿verdad?",
  ui_story_5067_50670501_34_dialog_content = "... Tienes miedo de que se conviertan en símbolos de miedo y dolor una vez más...",
  ui_story_5067_50670501_35_dialog_content = "Bien. Es solo que.",
  ui_story_5067_50670501_36_dialog_content = "Te ves tan lindo cuando estás preocupado...",
  ui_story_5067_50670501_37_dialog_content = "Pero no te preocupes, querido. Tienes muy poco que temer.",
  ui_story_5067_50670501_38_dialog_content = "A medida que esos pequeños recuperan lentamente su poder anterior, si ascenderán a un trono de terror...",
  ui_story_5067_50670501_39_dialog_content = "O convertirse en algo completamente diferente...",
  ui_story_5067_50670501_40_dialog_content = "Todo depende de tus pensamientos, Connolly. Después de todo, el único que puede controlarlos eres tú.",
  ui_story_5067_50670501_41_dialog_content = "Mis... pensamientos...?",
  ui_story_5067_50670501_42_dialog_content = "Entiendo. Haré... haré lo que creo que es correcto.",
  ui_story_5067_50670501_43_dialog_content = "Son mis compañeros importantes, así como los protectores de esta ciudad. Yo... no debería dudar de ellos así.",
  ui_story_5067_50670501_44_dialog_content = "Muy bien. Ahora ve y haz lo que sientes que es correcto, y hazlo con convicción. Estoy más que dispuesto a seguir ofreciendo mi consejo también.",
  ui_story_5067_50670501_45_dialog_content = "En cuanto a mi pago... Jeje, no te preocupes, querida, me aseguraré de darte un buen trato.",
