  ui_story_5067_50670601_13_dialog_content = "¡Muy bien! Realmente podríamos usar algunas manos más para terminar la reconstrucción del templo, ¡así que dirígete allí y ve qué necesitan!",
  ui_story_5067_50670601_14_dialog_content = "Como desees, Queen Connolly!",
