  ui_story_5067_50670601_25_dialog_content = "Pero más importante...",
  ui_story_5067_50670601_26_dialog_content = "¡Nuestro hogar! ¡Nuestro flamante hogar templo! ¡Mmm-mmm-mmm!",
  ui_story_5067_50670601_27_dialog_content = "En todo este tiempo, los Anton no se han calmado ni un poquito...",
  ui_story_5067_50670601_28_dialog_content = "Deben estar muy felices... ¿Qué les parece su nuevo hogar, chicos?",
  ui_story_5067_50670601_29_dialog_content = "¡Es perfecto, Connolly! ¡Te queremos mucho!",
  ui_story_5067_50670601_30_dialog_content = "Es aún más magnífico de lo que imaginábamos. Gracias.",
  ui_story_5067_50670601_31_dialog_content = "Nuestros recuerdos están volviendo lentamente.",
  ui_story_5067_50670601_32_dialog_content = "¿Eh? ¿Quieres decir... Estás empezando a recordar tu pasado?",
  ui_story_5067_50670601_33_dialog_content = "¡Sí, y mucho!",
  ui_story_5067_50670601_34_dialog_content = "Nuestra divinidad está regresando a nosotros mientras hablamos.",
  ui_story_5067_50670601_35_dialog_content = "El peso de nuestro poder y propósito.",
  ui_story_5067_50670601_36_dialog_content = "¿¡Qué?! Digo... ¿En serio? Estoy tan feliz por los tres...",
