  ui_story_5067_50670601_44_dialog_content = "Eres tú... el Delfín Blanco...",
  ui_story_5067_50670601_45_dialog_content = "¡Espérame! ¡Voy a buscarte!",
  ui_story_5067_50670801_1_dialog_content = "Jaa... Jaa... Delfín blanco... Pensé...",
  ui_story_5067_50670801_2_dialog_content = "Pensé que nunca volvería a saber de ti.",
  ui_story_5067_50670801_3_dialog_content = "No te preocupes. Siempre he estado justo a tu lado.",
  ui_story_5067_50670801_4_dialog_content = "Pero después de ver lo bien que lo has hecho todo este tiempo, pensé que esto sería lo mejor.",
  ui_story_5067_50670801_5_dialog_content = "¿Crees que... lo hice bien?",
  ui_story_5067_50670801_6_dialog_content = "Por supuesto. Y ahora, tú y los Antons han dominado el poder de un nuevo dios.",
  ui_story_5067_50670801_7_dialog_content = "Eh...?!",
  ui_story_5067_50670801_8_dialog_content = "Solo mira... Ahora puedes ver peces en cada calle del pueblo, ¿verdad?",
  ui_story_5067_50670801_9_dialog_content = "De hecho, incluso deberías poder ver el mundo exterior—",
  ui_story_5067_50670801_10_dialog_content = "E-Esto es increíble! ¡Se siente como un sueño!",
  ui_story_5067_50670801_11_dialog_content = "¿Podría estar soñando en este momento?",
  ui_story_5067_50670801_12_dialog_content = "¿Vaya? ¿Finalmente te diste cuenta?",
  ui_story_5067_50670801_13_dialog_content = "¿Eh...? Lo sabía...",
  ui_story_5067_50670801_14_dialog_content = "Pero este no es un sueño ordinario, Connolly.",
  ui_story_5067_50670801_15_dialog_content = "El miedo y el dolor que alguna vez representó el Aqua Lord en realidad son la fuente de tu poder latente.",
  ui_story_5067_50670801_16_dialog_content = "En el pasado, desarrollaste el poder de conectarte con el vacío para evitar el dolor y lidiar con tus miedos.",
  ui_story_5067_50670801_17_dialog_content = "Mi pasado... ya veo...",
  ui_story_5067_50670801_18_dialog_content = "En ese entonces, había mucho miedo y dolor del que quería escapar...",
